<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Historial de Timbres</title><style>
body{margin:0;background:#f3f5f8;color:#243247;font-family:system-ui,-apple-system,"Segoe UI",sans-serif}.wrap{max-width:1320px;margin:38px auto;padding:0 20px}header{display:flex;align-items:end;justify-content:space-between;margin-bottom:18px}h1{font-size:25px;margin:0}.card{background:#fff;border:1px solid #dfe5ec;border-radius:10px;overflow:auto}form{display:flex;gap:10px;align-items:end;flex-wrap:wrap;margin-bottom:16px}label{font-size:12px;color:#617087}input,select{display:block;margin-top:3px;padding:8px;border:1px solid #cbd5e1;border-radius:5px}button,a{padding:8px 11px;border:1px solid #c8d2df;border-radius:6px;background:#fff;color:#245da8;text-decoration:none;cursor:pointer}table{width:100%;border-collapse:collapse;min-width:1250px}th,td{padding:11px 12px;border-bottom:1px solid #edf0f4;text-align:left}th{font-size:12px;text-transform:uppercase;background:#f8fafc;color:#617087}.num{text-align:right;font-variant-numeric:tabular-nums}.muted{color:#708096}
</style></head><body><main class="wrap"><header><div><h1>Historial de Timbres</h1><span class="muted"><?= $issuer_id ? 'Emisor ' . (int)$issuer_id : 'Todos los emisores' ?></span></div><a href="<?= esc(site_url($base_path) . '?key=' . rawurlencode($key)) ?>">Volver a cuentas</a></header>
<form method="get" action="<?= esc(current_url()) ?>"><input type="hidden" name="key" value="<?= esc($key) ?>"><label>Tipo<select name="type"><option value="">Todos</option><?php foreach (['adjustment_credit','adjustment_debit','allocation','document_reservation','document_consumption','document_release','reconciliation_consumption','reconciliation_release','cancellation_request','cancellation_status_query'] as $option): ?><option value="<?= esc($option) ?>" <?= $type===$option?'selected':'' ?>><?= esc($option) ?></option><?php endforeach; ?></select></label><label>Desde<input type="date" name="from" value="<?= esc($from) ?>"></label><label>Hasta<input type="date" name="to" value="<?= esc($to) ?>"></label><button type="submit">Filtrar</button></form>
<section class="card"><table><thead><tr><th>Fecha</th><th>Emisor</th><th>Ambiente</th><th>Tipo</th><th>Cantidad</th><th>Disponible antes</th><th>Disponible después</th><th>Reservado antes</th><th>Reservado después</th><th>Motivo / referencia</th><th>Documento</th><th>Intento PAC</th><th>Cancelación</th></tr></thead><tbody>
<?php foreach($history as $row): ?><tr><td><?= esc($row['created_at']) ?></td><td><strong><?= esc($row['rfc']) ?></strong><br><span class="muted"><?= esc($row['legal_name']) ?></span></td><td><?= esc((string)($row['environment'] ?? 'development')) ?></td><td><?= esc($row['movement_type']) ?></td><td class="num"><?= number_format((int)$row['quantity']) ?></td><td class="num"><?= number_format((int)$row['available_before']) ?></td><td class="num"><?= number_format((int)$row['available_after']) ?></td><td class="num"><?= number_format((int)$row['reserved_before']) ?></td><td class="num"><?= number_format((int)$row['reserved_after']) ?></td><td><?= esc($row['reason']) ?><?php if(!empty($row['reference'])): ?><br><span class="muted"><?= esc($row['reference']) ?></span><?php endif; ?></td><td><?= $row['fiscal_document_id']!==null?(int)$row['fiscal_document_id']:'—' ?></td><td><?= $row['pac_attempt_id']!==null?(int)$row['pac_attempt_id']:'—' ?></td><td><?= $row['fiscal_cancellation_request_id']!==null?(int)$row['fiscal_cancellation_request_id']:'—' ?></td></tr><?php endforeach; ?>
<?php if(!$history): ?><tr><td colspan="13">No hay movimientos para los filtros seleccionados.</td></tr><?php endif; ?></tbody></table></section></main></body></html>
